import{_ as p,a0 as s,w as n,s as d,I as t,x as o,a1 as a,A as i,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"如何在 Linux 上设置密码策略 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上设置密码策略 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上设置密码策略 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上设置密码策略 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/How to set password policy on Linux","title":"如何在 Linux 上设置密码策略","tag":"201401","desc":""},"relativePath":"201401/How to set password policy on Linux.md","filePath":"[post].md"}'),u={name:"201401/How to set password policy on Linux.md"};function m(c,e,b,x,f,k){const r=s("Link");return n(),d("div",null,[e[15]||(e[15]=t("h1",{id:"如何在-linux-上设置密码策略",tabindex:"-1"},[o("如何在 Linux 上设置密码策略 "),t("a",{class:"header-anchor",href:"#如何在-linux-上设置密码策略","aria-label":"Permalink to “如何在 Linux 上设置密码策略”"},"​")],-1)),e[16]||(e[16]=t("p",null,[o("用户帐号管理是系统管理员最重要的工作之一。而密码安全是系统安全中最受关注的一块。在本教程中，我将为大家介绍"),t("strong",null,"如何在 Linux 上设置密码策略"),o("。")],-1)),t("p",null,[e[1]||(e[1]=o("假设你已经在你的 Linux 系统上使用了 ",-1)),a(r,{href:"http://www.linux-pam.org/"},{default:i(()=>[...e[0]||(e[0]=[o("PAM (Pluggable Authentication Modules，插入式验证模块)",-1)])]),_:1}),e[2]||(e[2]=o("，因为这些年所有的 Linux 发行版都在使用它。",-1))]),e[17]||(e[17]=l(`<h3 id="准备工作" tabindex="-1">准备工作 <a class="header-anchor" href="#准备工作" aria-label="Permalink to “准备工作”">​</a></h3><p>安装 PAM 的 cracklib 模块，cracklib 能提供额外的密码检查能力。</p><p>Debian、Ubuntu 或 Linux Mint 系统上：</p><pre><code>$ sudo apt-get install libpam-cracklib 
</code></pre><p>CentOS、Fedora、RHEL 系统已经默认安装了 cracklib PAM 模块，所以在这些系统上无需执行上面的操作。</p><p>为了强制实施密码策略，我们需要修改 /etc/pam.d 目录下的 PAM 配置文件。一旦修改，策略会马上生效。</p><p>注意：此教程中的密码策略只对非 root 用户有效，对 root 用户无效。</p><h3 id="禁止使用旧密码" tabindex="-1">禁止使用旧密码 <a class="header-anchor" href="#禁止使用旧密码" aria-label="Permalink to “禁止使用旧密码”">​</a></h3><p>找到同时有 “password” 和 “pam_unix.so” 字段并且附加有 “remember=5” 的那行，它表示禁止使用最近用过的5个密码（己使用过的密码会被保存在 /etc/security/opasswd 下面）。</p><p>Debian、Ubuntu 或 Linux Mint 系统上：</p><pre><code>$ sudo vi /etc/pam.d/common-password 
</code></pre><blockquote><p>password [success=1 default=ignore] pam_unix.so obscure sha512 remember=5</p></blockquote><p>CentOS、Fedora、RHEL 系统上：</p><pre><code>$ sudo vi /etc/pam.d/system-auth 
</code></pre><blockquote><p>password sufficient pam_unix.so sha512 shadow nullok try_first_pass use_authtok remember=5</p></blockquote><h3 id="设置最短密码长度" tabindex="-1">设置最短密码长度 <a class="header-anchor" href="#设置最短密码长度" aria-label="Permalink to “设置最短密码长度”">​</a></h3><p>找到同时有 “password” 和 “pam_cracklib.so” 字段并且附加有 “minlen=10” 的那行，它表示最小密码长度为（10 - 类型数量）。这里的 “类型数量” 表示不同的字符类型数量。PAM 提供4种类型符号作为密码（大写字母、小写字母、数字和标点符号）。如果你的密码同时用上了这4种类型的符号，并且你的 minlen 设为10，那么最短的密码长度允许是6个字符。</p><p>Debian、Ubuntu 或 Linux Mint 系统上：</p><pre><code>$ sudo vi /etc/pam.d/common-password 
</code></pre><blockquote><p>password requisite pam_cracklib.so retry=3 minlen=10 difok=3</p></blockquote><p>CentOS、Fedora、RHEL 系统上：</p><pre><code>$ sudo vi /etc/pam.d/system-auth 
</code></pre><blockquote><p>password requisite pam_cracklib.so retry=3 difok=3 minlen=10</p></blockquote><h3 id="设置密码复杂度" tabindex="-1">设置密码复杂度 <a class="header-anchor" href="#设置密码复杂度" aria-label="Permalink to “设置密码复杂度”">​</a></h3><p>找到同时有 “password” 和 “pam_cracklib.so” 字段并且附加有 “ucredit=-1 lcredit=-2 dcredit=-1 ocredit=-1” 的那行，它表示密码必须至少包含一个大写字母（ucredit），两个小写字母（lcredit），一个数字（dcredit）和一个标点符号（ocredit）。</p><p>Debian、Ubuntu 或 Linux Mint 系统上：</p><pre><code>$ sudo vi /etc/pam.d/common-password 
</code></pre><blockquote><p>password requisite pam_cracklib.so retry=3 minlen=10 difok=3 ucredit=-1 lcredit=-2 dcredit=-1 ocredit=-1</p></blockquote><p>CentOS、Fedora、RHEL 系统上：</p><pre><code>$ sudo vi /etc/pam.d/system-auth 
</code></pre><blockquote><p>password requisite pam_cracklib.so retry=3 difok=3 minlen=10 ucredit=-1 lcredit=-2 dcredit=-1 ocredit=-1</p></blockquote><h3 id="设置密码过期期限" tabindex="-1">设置密码过期期限 <a class="header-anchor" href="#设置密码过期期限" aria-label="Permalink to “设置密码过期期限”">​</a></h3><p>编辑 /etc/login.defs 文件，可以设置当前密码的有效期限，具体变量如下所示：</p><pre><code>$ sudo vi /etc/login.defs 
</code></pre><blockquote><p>PASS_MAX_DAYS 150 PASS_MIN_DAYS 0 PASS_WARN_AGE 7</p></blockquote><p>这些设置要求用户每6个月改变他们的密码，并且会提前7天提醒用户密码快到期了。</p><p>如果你想为每个用户设置不同的密码期限，使用 chage 命令。下面的命令可以查看某个用户的密码限期：</p><pre><code>$ sudo chage -l xmodulo 
</code></pre><blockquote><p>Last password change : Dec 30, 2013 Password expires : never Password inactive : never Account expires : never Minimum number of days between password change : 0 Maximum number of days between password change : 99999 Number of days of warning before password expires : 7</p></blockquote><p>默认情况下，用户的密码永不过期。</p><p>下面的命令用于修改 xmodulo 用户的密码期限：</p><pre><code>$ sudo chage -E 6/30/2014 -m 5 -M 90 -I 30 -W 14 xmodulo 
</code></pre><p>上面的命令将密码期限设为2014年6月3日。另外，修改密码的最短周期为5天，最长周期为90天。密码过期前14天会发送消息提醒用户，过期后帐号会被锁住30天。</p>`,43)),t("p",null,[a(r,{href:"http://www.flickr.com/photos/xmodulo/11640903324/"},{default:i(()=>[...e[3]||(e[3]=[t("img",{src:"http://farm4.staticflickr.com/3779/11640903324_474963b7bb.jpg",alt:""},null,-1)])]),_:1})]),e[18]||(e[18]=t("hr",null,null,-1)),t("p",null,[e[5]||(e[5]=o("via: ",-1)),a(r,{href:"http://xmodulo.com/2013/12/set-password-policy-linux.html"},{default:i(()=>[...e[4]||(e[4]=[o("http://xmodulo.com/2013/12/set-password-policy-linux.html",-1)])]),_:1})]),t("p",null,[e[8]||(e[8]=o("译者：",-1)),a(r,{href:"https://github.com/bazz2"},{default:i(()=>[...e[6]||(e[6]=[o("bazz2",-1)])]),_:1}),e[9]||(e[9]=o(" 校对：",-1)),a(r,{href:"https://github.com/carolinewuyan"},{default:i(()=>[...e[7]||(e[7]=[o("Caroline",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=o("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[o("LCTT",-1)])]),_:1}),e[13]||(e[13]=o(" 原创翻译，",-1)),a(r,{href:"http://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[o("Linux中国",-1)])]),_:1}),e[14]||(e[14]=o(" 荣誉推出",-1))])])}const g=p(u,[["render",m]]);export{L as __pageData,g as default};
